<script lang="ts">
  import { onMount, onDestroy, untrack } from 'svelte';
  import type { CallController, AudioSettings } from '../call/controller.svelte';
  import Icon from './Icon.svelte';
  import Modal from './Modal.svelte';
  let { call, close, complete }: { call: CallController; close: () => void; complete: () => void } = $props();
  let step = $state(0), devices = $state<MediaDeviceInfo[]>([]), mic = $state(untrack(() => call.audio.microphone)), speaker = $state(untrack(() => call.audio.speaker)), suppression = $state<AudioSettings['suppression']>(untrack(() => call.audio.suppression)), studio = $state(untrack(() => call.audio.studio)), meter = $state(0), testing = $state(false), recording = $state(false), remaining = $state(5), recordingUrl = $state(''), error = $state('');
  let stream: MediaStream | undefined, context: AudioContext | undefined, recorder: MediaRecorder | undefined, animation = 0, timeout: ReturnType<typeof setTimeout> | undefined, countdown: ReturnType<typeof setInterval> | undefined, player = $state<HTMLAudioElement>()!;
  async function enumerate() { try { devices = await navigator.mediaDevices?.enumerateDevices() ?? []; } catch { /* Default device remains available. */ } }
  function stopStream() { cancelAnimationFrame(animation); stream?.getTracks().forEach(t => t.stop()); stream = undefined; if (context) void context.close(); context = undefined; testing = false; meter = 0; }
  async function testMic() {
    stopStream(); error = '';
    try {
      if (!navigator.mediaDevices?.getUserMedia) throw new Error('Microphone access needs a supported browser on localhost or HTTPS.');
      stream = await navigator.mediaDevices.getUserMedia({ audio: { deviceId: mic !== 'default' ? { exact: mic } : undefined, echoCancellation: !studio, noiseSuppression: !studio && suppression !== 'Off', autoGainControl: !studio } });
      await enumerate(); context = new AudioContext(); const analyser = context.createAnalyser(); analyser.fftSize = 256; context.createMediaStreamSource(stream).connect(analyser); const data = new Uint8Array(analyser.fftSize);
      testing = true;
      const frame = () => { if (!testing) return; analyser.getByteTimeDomainData(data); meter = Math.min(1, Math.sqrt(data.reduce((s, v) => s + ((v - 128) / 128) ** 2, 0) / data.length) * 5); animation = requestAnimationFrame(frame); }; frame();
    } catch (e) { error = e instanceof Error && e.name === 'NotAllowedError' ? 'Microphone permission was declined. You can still explore the demo and check your sound later.' : `Couldn’t open the microphone. ${e instanceof Error ? e.message : ''}`; }
  }
  async function record() {
    if (!stream) await testMic(); if (!stream) return;
    if (!window.MediaRecorder) { error = 'Recording isn’t supported in this browser. The live meter still works.'; return; }
    if (recordingUrl) URL.revokeObjectURL(recordingUrl);
    const chunks: BlobPart[] = []; recorder = new MediaRecorder(stream); recorder.ondataavailable = e => { if (e.data.size) chunks.push(e.data); }; recorder.onstop = () => { if (chunks.length) recordingUrl = URL.createObjectURL(new Blob(chunks, { type: recorder?.mimeType ?? 'audio/webm' })); recording = false; clearInterval(countdown); }; recorder.start(); recording = true; remaining = 5;
    countdown = setInterval(() => remaining = Math.max(0, remaining - 1), 1000); timeout = setTimeout(() => { if (recorder?.state === 'recording') recorder.stop(); }, 5000);
  }
  async function playback() { try { if ('setSinkId' in player && speaker !== 'default') await (player as HTMLAudioElement & { setSinkId(id: string): Promise<void> }).setSinkId(speaker); await player.play(); } catch { error = 'Couldn’t play on that speaker. Try your default output.'; } }
  function finish() { call.configureAudio({ microphone: mic, speaker, suppression, studio }); localStorage.setItem('pingo-sound-checked', 'true'); complete(); }
  onMount(() => { void enumerate(); navigator.mediaDevices?.addEventListener('devicechange', enumerate); });
  onDestroy(() => { clearTimeout(timeout); clearInterval(countdown); if (recorder?.state === 'recording') { recorder.onstop = null; recorder.stop(); } stopStream(); if (recordingUrl) URL.revokeObjectURL(recordingUrl); navigator.mediaDevices?.removeEventListener('devicechange', enumerate); });
</script>
<Modal title="Let’s find your good sound." {close}>
  <div class="wizard-progress">{#each ['Your devices', 'Your voice', 'Your sound'] as label, i}<button class:active={step === i} class:complete={step > i} onclick={() => step = i}><span>{step > i ? '✓' : i + 1}</span>{label}</button>{/each}</div>
  {#if step === 0}<div class="wizard-illustration"><Icon name="headphones" size={55}/><span>Sound like yourself.</span></div><p class="settings-description">A quick sound check, so the first thing people hear is you.</p><label class="field">Microphone<select bind:value={mic} onchange={() => { if (testing) void testMic(); }}><option value="default">System default microphone</option>{#each devices.filter(d => d.kind === 'audioinput' && d.deviceId && d.deviceId !== 'default') as d}<option value={d.deviceId}>{d.label || `Microphone ${d.deviceId.slice(0, 4)}`}</option>{/each}</select></label><label class="field">Speaker<select bind:value={speaker}><option value="default">System default speaker</option>{#each devices.filter(d => d.kind === 'audiooutput' && d.deviceId && d.deviceId !== 'default') as d}<option value={d.deviceId}>{d.label || `Speaker ${d.deviceId.slice(0, 4)}`}</option>{/each}</select></label><div class="tip"><Icon name="headphones" size={17}/>Headphones help everyone sound a little clearer.</div>
  {:else if step === 1}<h3>A little hello, just for you.</h3><p class="settings-description">Say a few words. You’ll see your voice here, and you can play back a five-second clip. It stays on this device.</p><div class="mic-meter" role="meter" aria-label="Microphone input level" aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.round(meter * 100)}>{#each Array(32) as _, i}<span class:lit={i / 32 < meter}></span>{/each}</div><div class="inline-actions"><button class="button" onclick={testMic}><Icon name="mic" size={16}/>{testing ? 'Restart microphone' : 'Enable microphone'}</button><button class="button" disabled={recording} onclick={record}><Icon name={recording ? 'stop' : 'circle'} size={16}/>{recording ? `Recording… ${remaining}s` : 'Record 5 seconds'}</button><button class="button soft" disabled={!recordingUrl || recording} onclick={playback}><Icon name="play" size={16}/>Play back</button></div><audio bind:this={player} src={recordingUrl}></audio><p class="muted tiny">Your browser will ask before using your microphone.</p>
  {:else}<h3>A little less noise. A little more you.</h3><p class="settings-description">Choose what feels right. You can change this any time.</p><label class="field">Noise suppression<div class="segmented large">{#each ['Off', 'Gentle', 'Strong'] as mode}<button disabled={studio} class:active={suppression === mode} onclick={() => suppression = mode as AudioSettings['suppression']}>{mode}</button>{/each}</div></label><p class="settings-description">{studio ? 'Studio keeps all processing off so music and instruments keep their detail.' : suppression === 'Off' ? 'Your microphone, just as it is. Best in a quiet room.' : suppression === 'Gentle' ? 'Softens keyboard taps and background hum. A good everyday choice.' : 'Keeps busy rooms in the background. Your voice stays up front.'}</p><label class="setting-toggle"><span><strong>Studio</strong><small>For music, instruments, and all the little details.<br/>Turns off echo cancellation, noise suppression, and automatic volume.</small></span><input type="checkbox" role="switch" bind:checked={studio}/></label><div class="tip"><Icon name="music" size={17}/>Use headphones in Studio to keep echoes out.</div>{/if}
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  <div class="wizard-footer"><button class="text-button" onclick={step ? () => step-- : close}>{step ? 'Back a little' : 'Check later'}</button><span>{step + 1} of 3</span><button class="button primary" disabled={recording} onclick={() => step < 2 ? step++ : finish()}>{step < 2 ? 'Keep going' : 'Sounds good'}<Icon name={step < 2 ? 'arrowRight' : 'check'} size={16}/></button></div>
</Modal>
